import{_ as d,l,o as e,c as s,v as o,p as n,x as r,d as i,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"buddy 分配器","description":"","frontmatter":{"title":"buddy 分配器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/buddy-allocator.md","filePath":"cs/buddy-allocator.md","lastUpdated":1789023840000}'),u={name:"cs/buddy-allocator.md"};function E(h,a,A,b,m,_){const t=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="buddy-分配器" tabindex="-1">buddy 分配器 <a class="header-anchor" href="#buddy-分配器" aria-label="Permalink to &quot;buddy 分配器&quot;">​</a></h1><div class="epigraph"><p>物理内存按 2 的幂分块；分配时把大块劈成一对伙伴，释放时再与伙伴合并，减少外碎片。</p><footer>—— 据 Knowlton, A fast storage allocator, CACM 1965；Knuth TAOCP 对 buddy 系统的整理</footer></div><p><a href="/cs/mprotect">上一课</a>改的是用户虚权限。缺页、页表、<a href="/cs/huge-pages">大页</a> 都要内核拿出<strong>连续物理页</strong>。<a href="/cs/page-replace">置换</a>释放的也是帧。缺口是内核的页框分配器：不是 <code>malloc</code>，是按阶（order）管理空闲块。buddy 是经典实现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若用一张位图每次找 N 个连续帧，扫描太慢。若只用单页空闲表，2MB 大页经常拼不出。buddy：每阶一条空闲链表，块大小 2^k 页，地址对齐。分配 order=n：若该阶没有，从更高阶劈成两个伙伴。释放：看伙伴是否空闲，合并升阶。缺口不是虚地址布局，而是物理连续与对齐。</p><p>本课不把每节点 NUMA 的 zonelist 调参写完，只承认 DMA/普通区等 zone。</p><p><span class="marginnote">伙伴关系由地址决定：块基址 xor 块大小即伙伴。合并是 O(阶数)，不是扫全部内存。内碎片：只要了 3 页也得给 4 页。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>alloc_pages(order)</code> 从对应 zone 取块；失败则唤醒回收（后课 shrinker）或对调用者失败。大页需要高阶成功。单页（order 0）是缺页的常见路径。释放必须用原来的 order，否则破坏伙伴不变量。与用户堆对照：用户 brk 切的是虚区间；这里切的是 DRAM 帧。</p>',9)),(e(),n(p,null,{default:r(()=>[c(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%A6%81%202%5En%20%E9%A1%B5%22%5D%20--%3E%20HIT%7B%22%E8%AF%A5%E9%98%B6%E7%A9%BA%E9%97%B2%3F%22%7D%0A%20%20HIT%20--%3E%7C%E6%9C%89%7C%20GIVE%5B%22%E4%BA%A4%E5%87%BA%E5%AF%B9%E9%BD%90%E5%9D%97%22%5D%0A%20%20HIT%20--%3E%7C%E6%97%A0%7C%20SPLIT%5B%22%E5%8A%88%E6%9B%B4%E9%AB%98%E9%98%B6%22%5D%0A%20%20FREE%5B%22%E9%87%8A%E6%94%BE%22%5D%20--%3E%20MERGE%5B%22%E4%BC%99%E4%BC%B4%E7%A9%BA%E5%88%99%E5%90%88%E5%B9%B6%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>buddy 让物理连续成为一等公民：DMA、大页、某些内核栈都要它。外碎片表现为高阶链表空、低阶很碎——回收与压缩（后课）试图拼回高阶。不要把 buddy 写成文件系统的块分配；inode 的块位图是另一层。</p><p><a href="/cs/paging-vm">分页</a> 把这些帧填进 PTE；分配器不关心 VPN。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 CMA、内存热插拔的全部状态机。不保证碎片在长时间运行后仍能给出 1GB 页。内核小对象若直接用 order 0 再自己切，浪费页表级对齐——下一课 slab 在页内切对象。</p><p>后课默认：内核能按 2^n 页拿到帧。频繁的几十字节对象不应各占一页，下一课 slab。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>buddy 用伙伴合并管理 2^n 物理块，服务大页与 DMA。</li><li>内碎片换来分配与合并的速度。</li><li>页内小对象缓存是 slab 的缺口。</li><li>出处：Knowlton, <em>CACM</em> 1965；Knuth, <em>TAOCP</em>；Bovet and Cesati, <em>ULK</em>。</li></ul>',8))])}const T=d(u,[["render",E]]);export{f as __pageData,T as default};
